CREATE OR REPLACE FUNCTION workforce_private.attendance_payroll_before_unpaid(p_employee uuid, p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare tick timestamptz:=workforce_private.work_now(); emp public.wf_employees; d date; first_day date; last_day date;
 workdays integer[]; daily integer; required numeric:=0; credited numeric:=0; missing numeric:=0;
 seconds numeric; gap numeric; fixed numeric; adjustment numeric:=0; day_rate numeric; last_rate numeric;
 covered_days integer:=0; missing_days jsonb:='[]'; weekly jsonb; term record; activated date; cutoff_on date; leave_day boolean; sick jsonb;
begin
 select * into emp from public.wf_employees where id=p_employee;
 if not found then raise sqlstate 'P0002' using message='الموظفة غير متاحة';end if;
 select p.starts_on,p.cutoff_on into activated,cutoff_on from workforce_private.payroll_attendance_policy p where id;
 select s.workdays,s.daily_minutes into workdays,daily from public.wf_attendance_settings s where s.employee_id=p_employee;
 workdays:=coalesce(workdays,array[0,1,2,3,4,6]);daily:=coalesce(daily,480);
 first_day:=greatest(p_month,emp.start_date,activated);
 last_day:=least((p_month+interval '1 month - 1 day')::date,
   (tick at time zone 'Asia/Riyadh')::date-case when (tick at time zone 'Asia/Riyadh')::date>=cutoff_on and (tick at time zone 'Asia/Riyadh')::time>=workforce_private.employee_work_end(p_employee,(tick at time zone 'Asia/Riyadh')::date) then 0 else 1 end);
 weekly:=workforce_private.weekly_hours(p_employee,p_month); for d in select generate_series(first_day::timestamp,last_day::timestamp,interval '1 day')::date loop
  if extract(dow from d)::integer<>all(workdays) then continue;end if;
  if to_char(d,'MM-DD') in ('02-22','09-23') or exists(select 1 from public.wf_paid_calendar_days h where h.day=d) then continue;end if;
  select exists(select 1 from public.wf_employee_requests q where q.employee_id=p_employee and q.test_run_id is null
    and q.kind='leave' and q.leave_type in ('paid','sick') and q.status='approved' and d between (q.starts_at at time zone 'Asia/Riyadh')::date and (q.ends_at at time zone 'Asia/Riyadh')::date) into leave_day;
  if leave_day then continue;end if;
  -- A missing salary version is not a zero-wage working day. Fail closed.
  select c.basic_salary+coalesce((select sum((a->>'amount')::numeric) from jsonb_array_elements(c.allowances) a),0) monthly
   into term from public.wf_compensation_versions c where c.employee_id=p_employee and c.effective_from<=d order by c.effective_from desc,c.revision desc limit 1;
  if not found then raise sqlstate 'PT409' using message='أكملي إعداد راتب الموظفة للفترة أولًا';end if;
  fixed:=term.monthly;day_rate:=fixed/30/8;last_rate:=day_rate;
  with ranges as (
   select greatest(lower(r),d::timestamp at time zone 'Asia/Riyadh') lo,
    least(upper(r),(case when d<cutoff_on then (d+1)::timestamp else d+workforce_private.employee_work_end(p_employee,d) end) at time zone 'Asia/Riyadh') hi
   from public.wf_attendance_sessions a cross join lateral workforce_private.work_credit_ranges(a,tick) r
   where a.employee_id=p_employee and a.checked_in<((d+1)::timestamp at time zone 'Asia/Riyadh')
    and (a.checked_out>=(d::timestamp at time zone 'Asia/Riyadh') or a.checked_out is null)
   union all
   select greatest(q.starts_at,(d+workforce_private.employee_work_start(p_employee,d)) at time zone 'Asia/Riyadh'),least(q.ends_at,(d+workforce_private.employee_work_end(p_employee,d)) at time zone 'Asia/Riyadh')
   from public.wf_employee_requests q where q.employee_id=p_employee and q.test_run_id is null and q.kind='permission' and q.status='approved'
    and q.starts_at<((d+1)::timestamp at time zone 'Asia/Riyadh') and q.ends_at>(d::timestamp at time zone 'Asia/Riyadh')
  ), merged as(select range_agg(tstzrange(lo,hi,'[)')) rr from ranges where hi>lo)
  select least(daily*60,coalesce(sum(extract(epoch from upper(r)-lower(r))),0)) into seconds from merged cross join lateral unnest(rr) r;
  seconds:=coalesce((select least(daily*60,(v->>'base_credited_seconds')::numeric+(v->>'applied_seconds')::numeric) from jsonb_array_elements(weekly->'days') v where v->>'day'=d::text),seconds); gap:=greatest(0,daily*60-seconds);required:=required+daily*60;credited:=credited+seconds;missing:=missing+gap;
  adjustment:=adjustment+day_rate*gap/3600;covered_days:=covered_days+1;
  if gap>0 then missing_days:=missing_days||jsonb_build_array(jsonb_build_object('day',d,'required_seconds',daily*60,'credited_seconds',seconds,'missing_seconds',gap,'hourly_rate',round(day_rate,6)::text));end if;
 end loop;
 if last_rate is null then
  select (c.basic_salary+coalesce((select sum((a->>'amount')::numeric) from jsonb_array_elements(c.allowances) a),0))/30/8 into last_rate
   from public.wf_compensation_versions c where c.employee_id=p_employee and c.effective_from<=least((p_month+interval '1 month - 1 day')::date,(tick at time zone 'Asia/Riyadh')::date)
   order by c.effective_from desc,c.revision desc limit 1;
 end if;
 sick:=workforce_private.sick_payroll(p_employee,p_month,(tick at time zone 'Asia/Riyadh')::date);
 adjustment:=adjustment+(sick->>'amount')::numeric;
 return jsonb_build_object('weekly_compensation',weekly-'as_of','sick_leave',sick,'starts_on',activated,'through',case when last_day>=first_day then last_day else null end,
  'required_seconds',required,'credited_seconds',credited,'missing_seconds',missing,'days',covered_days,
  'hourly_rate',round(last_rate,6)::text,'calculated_amount',case when exists(select 1 from workforce_private.payroll_attendance_waivers w where w.employee_id=p_employee and w.month=p_month) then '0.00' else round(adjustment,2)::text end,
  'waived_amount',case when exists(select 1 from workforce_private.payroll_attendance_waivers w where w.employee_id=p_employee and w.month=p_month) then round(adjustment,2)::text else '0.00' end,
  'waiver_reason',(select w.reason from workforce_private.payroll_attendance_waivers w where w.employee_id=p_employee and w.month=p_month),'missing_days',missing_days);
end $function$

CREATE OR REPLACE FUNCTION workforce_private.daily_payroll_accrual_before_unpaid(p wf_monthly_payroll)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare tick timestamptz:=workforce_private.work_now(); today date:=(tick at time zone 'Asia/Riyadh')::date;
 first_day date; last_day date:=(p.month+interval '1 month - 1 day')::date; cutoff date;
 days_total integer; days_elapsed integer; ratio numeric:=0; base numeric:=p.basic_amount+p.allowances_amount;
 gross numeric:=0; insurance numeric:=0; other numeric:=0; settlement numeric:=0; pending numeric:=0;
 credited numeric:=0; daily integer; workdays integer[]; paid_day boolean; term record; hourly numeric;
 detail jsonb; final boolean; day_gap numeric:=0; result numeric; award numeric;
 policy public.wf_employee_insurance_settings; insured_start date; insured_day date; insured_basis numeric:=0; insured_term numeric; insured_denominator numeric;
begin
 select greatest(p.month,e.start_date) into first_day from public.wf_employees e where e.id=p.employee_id;
 select cutoff_on into cutoff from workforce_private.payroll_attendance_policy where id;
 final:=p.status='paid' or today>last_day or today=last_day and today>=cutoff and (tick at time zone 'Asia/Riyadh')::time>=workforce_private.employee_work_end(p.employee_id,(tick at time zone 'Asia/Riyadh')::date);
 select coalesce(sum((d->>'amount')::numeric) filter(where d->>'kind'='insurance'),0),
  coalesce(sum((d->>'amount')::numeric) filter(where d->>'kind'<>'insurance'),0) into insurance,other from jsonb_array_elements(p.deductions) d;
 if final then
  return jsonb_build_object('starts_on',first_day,'through',last_day,'as_of',tick,'closed',true,
   'gross_amount',p.gross_amount::text,'insurance_amount',insurance::text,'other_amount',other::text,
   'attendance_amount',p.attendance_amount::text,'total_amount',p.total_amount::text,'current_credited_seconds',0);
 end if;
 days_total:=greatest(1,last_day-first_day+1);days_elapsed:=greatest(0,least(today,last_day)-first_day+1);
 ratio:=least(1,days_elapsed::numeric/days_total);
 -- The joining-month salary already uses the approved /30 proration. Distribute
 -- that period over its calendar days; a full month always accrues exactly its salary.
 gross:=base*ratio;insurance:=round(insurance*ratio,2);
 -- Calculate the contribution from source wages, not from an already-rounded
 -- monthly contribution. This also respects a later insurance effective date.
 select * into policy from public.wf_employee_insurance_settings where employee_id=p.employee_id;
 if found then
  insured_start:=greatest(first_day,policy.effective_from);
  insured_denominator:=case when insured_start>p.month then 30 else extract(day from last_day) end;
  for insured_day in select generate_series(insured_start::timestamp,least(today,last_day)::timestamp,interval '1 day')::date loop
   select c.basic_salary+coalesce((select sum((a->>'amount')::numeric) from jsonb_array_elements(c.allowances) a where coalesce(a->>'name','') ~* '(سكن|housing)'),0)
    into insured_term from public.wf_compensation_versions c where c.employee_id=p.employee_id and c.effective_from<=insured_day order by c.effective_from desc,c.revision desc limit 1;
   if not found then raise sqlstate 'PT409' using message='أكملي إعداد الراتب الأساسي وبدل السكن أولًا';end if;
   insured_basis:=insured_basis+insured_term;
  end loop;
  insurance:=round(insured_basis/insured_denominator*policy.rate/100,2);
 end if;
 detail:=workforce_private.attendance_payroll(p.employee_id,p.month);
 settlement:=(detail->>'calculated_amount')::numeric;
 if today between first_day and last_day then
  select s.daily_minutes,s.workdays into daily,workdays from public.wf_attendance_settings s where s.employee_id=p.employee_id;
  daily:=coalesce(daily,480);workdays:=coalesce(workdays,array[0,1,2,3,4,6]);
  paid_day:=extract(dow from today)::integer<>all(workdays) or to_char(today,'MM-DD') in ('02-22','09-23')
   or exists(select 1 from public.wf_paid_calendar_days where day=today)
   or exists(select 1 from public.wf_employee_requests q where q.employee_id=p.employee_id and q.test_run_id is null
    and q.kind='leave' and q.status='approved' and q.leave_type in ('paid','sick')
    and today between (q.starts_at at time zone 'Asia/Riyadh')::date and (q.ends_at at time zone 'Asia/Riyadh')::date);
  if not paid_day and not workforce_private.is_unpaid_leave(p.employee_id,today) then
   select (c.basic_salary+coalesce((select sum((a->>'amount')::numeric) from jsonb_array_elements(c.allowances) a),0))/30/8 hourly
    into term from public.wf_compensation_versions c where c.employee_id=p.employee_id and c.effective_from<=today order by c.effective_from desc,c.revision desc limit 1;
   if not found then raise sqlstate 'PT409' using message='أكملي إعداد راتب الموظفة للفترة أولًا';end if;
   hourly:=term.hourly;
   with ranges as (
    select greatest(lower(r),today::timestamp at time zone 'Asia/Riyadh') lo,
     least(upper(r),tick,(case when today<cutoff then (today+1)::timestamp else today+workforce_private.employee_work_end(p.employee_id,today) end) at time zone 'Asia/Riyadh') hi
    from public.wf_attendance_sessions a cross join lateral workforce_private.work_credit_ranges(a,tick) r
    where a.employee_id=p.employee_id and a.checked_in<((today+1)::timestamp at time zone 'Asia/Riyadh')
     and (a.checked_out>=today::timestamp at time zone 'Asia/Riyadh' or a.checked_out is null)
    union all
    select greatest(q.starts_at,(today+workforce_private.employee_work_start(p.employee_id,today)) at time zone 'Asia/Riyadh'),least(q.ends_at,(today+workforce_private.employee_work_end(p.employee_id,today)) at time zone 'Asia/Riyadh',tick)
    from public.wf_employee_requests q where q.employee_id=p.employee_id and q.test_run_id is null and q.kind='permission' and q.status='approved'
     and q.starts_at<((today+1)::timestamp at time zone 'Asia/Riyadh') and q.ends_at>today::timestamp at time zone 'Asia/Riyadh'
   ), merged as(select range_agg(tstzrange(lo,hi,'[)')) rr from ranges where hi>lo)
   select least(daily*60,coalesce(sum(extract(epoch from upper(r)-lower(r))),0)) into credited from merged cross join lateral unnest(rr) r;
   credited:=coalesce((select least(daily*60,(v->>'base_credited_seconds')::numeric+(v->>'applied_seconds')::numeric) from jsonb_array_elements(detail->'weekly_compensation'->'days') v where v->>'day'=today::text),credited); day_gap:=greatest(0,daily*60-credited)*hourly/3600;
   if (detail->>'through')::date=today then
    -- At 17:00 the monthly settlement includes today. Keep it exactly once.
    settlement:=greatest(0,settlement-round(day_gap,2));
   end if;
   pending:=least(base/days_total,day_gap);
  end if;
 end if;
 -- Recorded incentives are earned when entered; future salary is never included.
 award:=case when days_elapsed>0 then greatest(0,p.gross_amount-base) else 0 end;
 gross:=round(greatest(0,gross-pending)+award,2);settlement:=round(least(settlement,greatest(0,gross-insurance-other)),2);
 result:=greatest(0,gross-insurance-other-settlement)+p.reimbursement_amount;
 return jsonb_build_object('starts_on',first_day,'through',case when days_elapsed>0 then least(today,last_day) else null end,
  'as_of',tick,'closed',false,'gross_amount',gross::text,'insurance_amount',insurance::text,'other_amount',other::text,
  'attendance_amount',settlement::text,'total_amount',result::text,'current_credited_seconds',credited);
end $function$

CREATE OR REPLACE FUNCTION workforce_private.insurance_payroll(p_employee uuid, p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare policy public.wf_employee_insurance_settings; joined date; d date; first_day date; last_day date:=(p_month+interval '1 month - 1 day')::date;
 basis numeric; total_basis numeric:=0; denominator numeric; term record;
begin
 select * into policy from public.wf_employee_insurance_settings where employee_id=p_employee;
 if not found or policy.effective_from>last_day then return null;end if;
 select start_date into joined from public.wf_employees where id=p_employee;
 first_day:=greatest(joined,policy.effective_from,p_month);
 denominator:=case when first_day>p_month then 30 else extract(day from last_day) end;
 for d in select generate_series(first_day::timestamp,last_day::timestamp,interval '1 day')::date loop
  select c.basic_salary+coalesce((select sum((a->>'amount')::numeric) from jsonb_array_elements(c.allowances) a where coalesce(a->>'name','') ~* '(سكن|housing)'),0) insurance_basis
   into term from public.wf_compensation_versions c where c.employee_id=p_employee and c.effective_from<=d order by c.effective_from desc,c.revision desc limit 1;
  if not found then raise sqlstate 'PT409' using message='أكملي إعداد الراتب الأساسي وبدل السكن أولًا';end if;
  basis:=term.insurance_basis;total_basis:=total_basis+basis;
 end loop;
 return jsonb_build_object('amount',round(total_basis/denominator*policy.rate/100,2)::text,'rate',policy.rate::text,'basis_amount',round(total_basis/denominator,2)::text,
  'reference','auto:gosi:'||to_char(p_month,'YYYY-MM'));
end $function$

CREATE OR REPLACE FUNCTION workforce_private.weekly_hours(p_employee uuid, p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare tick timestamptz:=workforce_private.work_now(); today date:=(tick at time zone 'Asia/Riyadh')::date;
 first_day date; last_day date; activation date; cutoff date; joined date; d date; week_start date;
 workdays integer[]; daily integer; actual numeric; credit numeric; lo timestamptz; hi timestamptz;
 days jsonb:='[]'; transfers jsonb:='[]'; weeks jsonb:='[]'; saved jsonb; current_week jsonb;
 i integer; j integer; balance numeric; take numeric; target_gap numeric; week_target numeric; w record;
begin
 if p_month is null or extract(day from p_month)<>1 then raise sqlstate 'PT400' using message='الشهر غير صحيح';end if;
 select start_date into joined from public.wf_employees where id=p_employee;
 if not found then raise sqlstate 'P0002' using message='الموظفة غير متاحة';end if;
 -- Preserve a paid month's exact allocation, including its unused balance.
 select attendance_details->'weekly_compensation' into saved from public.wf_monthly_payroll where employee_id=p_employee and month=p_month and status='paid';
 if found then return coalesce(saved,jsonb_build_object('enabled',false,'days','[]'::jsonb,'weeks','[]'::jsonb,'transfers','[]'::jsonb));end if;
 select starts_on into activation from workforce_private.weekly_hours_policy where id;
 select cutoff_on into cutoff from workforce_private.payroll_attendance_policy where id;
 select s.workdays,s.daily_minutes into workdays,daily from public.wf_attendance_settings s where s.employee_id=p_employee;
 workdays:=coalesce(workdays,array[0,1,2,3,4,6]);daily:=coalesce(daily,480);
 first_day:=greatest(p_month,joined,activation);last_day:=(p_month+interval '1 month - 1 day')::date;
 for d in select generate_series(first_day::timestamp,least(today,last_day)::timestamp,interval '1 day')::date loop
  if extract(dow from d)::integer<>all(workdays) or to_char(d,'MM-DD') in ('02-22','09-23')
   or exists(select 1 from public.wf_paid_calendar_days h where h.day=d)
   or exists(select 1 from public.wf_employee_requests q where q.employee_id=p_employee and q.test_run_id is null and q.kind='leave' and q.status='approved'
    and d between (q.starts_at at time zone 'Asia/Riyadh')::date and (q.ends_at at time zone 'Asia/Riyadh')::date) then continue;end if;
  lo:=d::timestamp at time zone 'Asia/Riyadh';
  hi:=least(tick,(case when d<cutoff then (d+1)::timestamp else d+workforce_private.employee_work_end(p_employee,d) end) at time zone 'Asia/Riyadh');
  -- Only genuine regular attendance can earn surplus. Approved missing-hour
  -- credits and paid permission can fill a gap but can never mint surplus.
  with ranges as (
   select greatest(lower(r),lo) a,least(upper(r),hi) b
   from public.wf_attendance_sessions s cross join lateral workforce_private.work_credit_ranges(s,tick) r
   where s.employee_id=p_employee and s.credit_request_id is null and s.overtime_request_id is null
    and s.checked_in<hi and (s.checked_out>lo or s.checked_out is null)
  ), overtime as (
   select range_agg(tstzrange(q.starts_at,q.ends_at,'[)')) rr from public.wf_employee_requests q
   where q.employee_id=p_employee and q.kind='overtime' and q.status='approved' and q.test_run_id is null and q.starts_at<hi and q.ends_at>lo
  ), regular as (
   select unnest(tstzmultirange(tstzrange(a,b,'[)'))-coalesce((select rr from overtime),'{}'::tstzmultirange)) r from ranges where b>a
  ), merged as(select range_agg(r) rr from regular)
  select coalesce(sum(extract(epoch from upper(r)-lower(r))),0) into actual from merged cross join lateral unnest(rr) r;
  with ranges as (
   select greatest(lower(r),lo) a,least(upper(r),hi) b
   from public.wf_attendance_sessions s cross join lateral workforce_private.work_credit_ranges(s,tick) r
   where s.employee_id=p_employee and s.overtime_request_id is null and s.checked_in<hi and (s.checked_out>lo or s.checked_out is null)
   union all
   select greatest(q.starts_at,(d+workforce_private.employee_work_start(p_employee,d)) at time zone 'Asia/Riyadh'),least(q.ends_at,hi)
   from public.wf_employee_requests q where q.employee_id=p_employee and q.test_run_id is null and q.kind='permission' and q.status='approved' and q.starts_at<hi and q.ends_at>lo
  ), overtime as (
   select range_agg(tstzrange(q.starts_at,q.ends_at,'[)')) rr from public.wf_employee_requests q
   where q.employee_id=p_employee and q.kind='overtime' and q.status='approved' and q.test_run_id is null and q.starts_at<hi and q.ends_at>lo
  ), regular as (
   select unnest(tstzmultirange(tstzrange(a,b,'[)'))-coalesce((select rr from overtime),'{}'::tstzmultirange)) r from ranges where b>a
  ), merged as(select range_agg(r) rr from regular)
  select least(daily*60,coalesce(sum(extract(epoch from upper(r)-lower(r))),0)) into credit from merged cross join lateral unnest(rr) r;
  week_start:=d-((extract(dow from d)::integer+1)%7);
  days:=days||jsonb_build_array(jsonb_build_object('day',d,'week_start',week_start,'required_seconds',daily*60,
   'attendance_seconds',actual,'base_credited_seconds',credit,'generated_seconds',greatest(0,actual-daily*60),
   'unused_seconds',greatest(0,actual-daily*60),'applied_seconds',0,'missing_seconds',greatest(0,daily*60-credit)));
 end loop;
 -- Deterministic FIFO allocation. All source/target days are already elapsed;
 -- allocations cannot cross an employee, Saturday boundary or payroll month.
 for i in 0..jsonb_array_length(days)-1 loop
  balance:=(days->i->>'unused_seconds')::numeric;
  for j in 0..jsonb_array_length(days)-1 loop
   exit when balance<=0;
   if days->i->>'week_start'<>days->j->>'week_start' then continue;end if;
   target_gap:=(days->j->>'missing_seconds')::numeric;take:=least(balance,target_gap);
   if take<=0 then continue;end if;
   days:=jsonb_set(days,array[j::text,'applied_seconds'],to_jsonb((days->j->>'applied_seconds')::numeric+take));
   days:=jsonb_set(days,array[j::text,'missing_seconds'],to_jsonb(target_gap-take));balance:=balance-take;
   transfers:=transfers||jsonb_build_array(jsonb_build_object('source_day',days->i->>'day','target_day',days->j->>'day','seconds',take));
  end loop;
  days:=jsonb_set(days,array[i::text,'unused_seconds'],to_jsonb(balance));
 end loop;
 for w in select (v->>'week_start')::date starts_on,sum((v->>'attendance_seconds')::numeric) actual,
   sum((v->>'generated_seconds')::numeric) generated,sum((v->>'applied_seconds')::numeric) applied,
   sum((v->>'base_credited_seconds')::numeric) base,sum((v->>'unused_seconds')::numeric) unused
  from jsonb_array_elements(days) v group by v->>'week_start' order by v->>'week_start' loop
  select count(*)*daily*60 into week_target from generate_series(greatest(w.starts_on,first_day)::timestamp,least(w.starts_on+6,last_day)::timestamp,interval '1 day') x
   where extract(dow from x)::integer=any(workdays) and to_char(x,'MM-DD') not in ('02-22','09-23')
   and not exists(select 1 from public.wf_paid_calendar_days h where h.day=x::date)
   and not exists(select 1 from public.wf_employee_requests q where q.employee_id=p_employee and q.test_run_id is null and q.kind='leave' and q.status='approved'
    and x::date between (q.starts_at at time zone 'Asia/Riyadh')::date and (q.ends_at at time zone 'Asia/Riyadh')::date);
  weeks:=weeks||jsonb_build_array(jsonb_build_object('starts_on',greatest(w.starts_on,first_day),'ends_on',least(w.starts_on+6,last_day),
   'generated_seconds',w.generated,'applied_seconds',w.applied,'attendance_seconds',w.actual,'credited_seconds',w.base+w.applied,'target_seconds',week_target,
   'available_seconds',case when today<=least(w.starts_on+6,last_day) then least(w.unused,greatest(0,week_target-w.base-w.applied)) else 0 end,
   'expired_seconds',case when today>least(w.starts_on+6,last_day) then w.unused else 0 end));
 end loop;
 select v into current_week from jsonb_array_elements(weeks) v where today between (v->>'starts_on')::date and (v->>'ends_on')::date;
 return jsonb_build_object('enabled',first_day<=last_day,'starts_on',activation,'as_of',tick,'days',days,'weeks',weeks,'transfers',transfers,'current_week',current_week,
  'applied_seconds',coalesce((select sum((v->>'applied_seconds')::numeric) from jsonb_array_elements(days) v),0),
